    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createChild>>, TError,CreateChildMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createChild>>, TError,CreateChildMutationVariables, TContext> => {

const mutationKey = getCreateChildMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createChild>>, CreateChildMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  createChild(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateChildMutationResult = NonNullable<Awaited<ReturnType<typeof createChild>>>
    export type CreateChildMutationBody = BodyType<CreateChildInput>
    export type CreateChildMutationError = ErrorType<Error | UnauthorizedResponse>
    export type CreateChildMutationVariables = {data: BodyType<CreateChildInput>}

    /**
 * @summary Create a child profile for the signed-in parent
 */
export const useCreateChild = <TError = ErrorType<Error | UnauthorizedResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createChild>>, TError,CreateChildMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof createChild>>,
        TError,
        CreateChildMutationVariables,
        TContext
      > => {
      return useMutation(getCreateChildMutationOptions(options), queryClient);
    }

export const getUpdateChildUrl = (id: number,) => {




  return `/api/children/${id}`
}

/**
 * @summary Update editable details of a child profile
 */
export const updateChild = async (id: number,
    updateChildInput: UpdateChildInput, options?: Parameters<typeof customFetch>[1]): Promise<ChildProfile> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<ChildProfile>(getUpdateChildUrl(id),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(updateChildInput)
  }
);}





